#include <iostream>
#include <string>
#include <algorithm>
#include <vector>

// Demonstrating the core mechanics of character extraction and reverse display
int main() {
    std::cout << "Enter a line of text:\n";

    std::string sentence;
    if (std::getline(std::cin, sentence)) {
        // Display reversed text (equivalent to recursive reverse with putchar)
        std::cout << "The line printed backward is:\n";
        for (auto it = sentence.rbegin(); it != sentence.rend(); ++it) {
            std::cout.put(*it);
        }
        std::cout << '\n';

        // Inspecting character-by-character processing similar to getchar
        std::cout << "Character codes:";
        for (unsigned char ch : sentence) {
            std::cout << ' ' << static_cast<int>(ch);
        }
        std::cout << '\n';
    }
    return 0;
}

#include <iostream>
#include <iomanip>
#include <sstream>
#include <string>
#include <cstdio>

int main() {
    // Part 1: Formatting into buffer (Legacy snprintf vs Modern C++ ostringstream)
    int x = 298;
    double y = 87.375;

    // Safe C-style formatted output into memory buffer using snprintf
    char buffer[80];
    std::snprintf(buffer, sizeof(buffer), "integer:%6d\ndouble:%7.2f", x, y);
    std::cout << "The formatted output stored in buffer is:\n" << buffer << "\n\n";

    // Modern C++17 type-safe formatting
    std::ostringstream oss;
    oss << "integer:" << std::setw(6) << x << "\ndouble:" << std::setw(7) << std::fixed << std::setprecision(2) << y;
    std::string formatted_str = oss.str();

    // Part 2: Parsing from string (Legacy sscanf vs Modern C++ istringstream)
    const char s[] = "31298 87.375";
    int parsed_x = 0;
    double parsed_y = 0.0;

    std::istringstream iss(s);
    if (iss >> parsed_x >> parsed_y) {
        std::cout << "The values parsed from string are:\n";
        std::cout << "integer:" << std::setw(6) << parsed_x << "\n";
        std::cout << "double: " << std::setw(7) << std::fixed << std::setprecision(3) << parsed_y << '\n';
    }

    return 0;
}
